import networkx as nx
from itertools import product

# For every connected graph G (up to n=7) and every RDF f:
# Is min_{u in V} ecc(u) <= W - 1?
# That is literally radius(G) <= W - 1, which is radius(G) + 1 <= W!

# But is there always u in V_2 with ecc(u) <= W - 1?
# Let's test!
failed_V2 = []
for n in range(2, 8):
    for G in nx.graph_atlas_g():
        if G.number_of_nodes() == n and nx.is_connected(G):
            nodes = list(G.nodes())
            for assignment in product([0, 1, 2], repeat=n):
                f = dict(zip(nodes, assignment))
                # check if RDF
                if not all(f[v] != 0 or any(f[u] == 2 for u in G.neighbors(v)) for v in nodes):
                    continue
                W = sum(assignment)
                V2 = [v for v in nodes if f[v] == 2]
                if V2:
                    min_ecc_V2 = min(nx.eccentricity(G, u) for u in V2)
                    if min_ecc_V2 > W - 1:
                        failed_V2.append((n, list(G.edges()), assignment, min_ecc_V2, W))

print(f'Total cases where no u in V_2 has ecc(u) <= W - 1: {len(failed_V2)}')
if failed_V2:
    print('Sample failure:', failed_V2[0])
